$ErrorActionPreference = "Stop"
Set-Location "C:\Projects\thoop-recovery"
$encoded = ""
$patch = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($encoded))
$patch | py -3 -
if ($LASTEXITCODE -ne 0) { throw "Source update failed." }
Write-Host "`n===== SOURCE CHECK =====" -ForegroundColor Cyan
git diff --check
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed." }
git diff --stat -- android/app/src/main/java/com/noop/ui/TodayScreen.kt android/app/src/main/java/com/noop/ui/WorkoutsScreen.kt
$estimated = git grep -n -I -- "Estimated Oxygen" android/app/src/main/java/com/noop/ui/TodayScreen.kt
if ($estimated) { throw "Estimated Oxygen still exists in TodayScreen.kt" }
Write-Host "[OK] Estimated Oxygen removed from Today UI" -ForegroundColor Green
Write-Host "`n===== COMPILE =====" -ForegroundColor Cyan
Set-Location ".\android"
.\gradlew.bat :app:compileFullDebugKotlin --no-daemon
if ($LASTEXITCODE -ne 0) { throw "Kotlin compile failed." }
Write-Host "[OK] Kotlin compile passed" -ForegroundColor Green
